import csv
import io
from datetime import date, datetime, timedelta


def main(input_data):
    today = datetime.now().astimezone().date()
    week = {today - timedelta(days=i) for i in range(7)}
    days = {}      # habit -> {date: total}
    for r in csv.reader(io.StringIO(input_data.get("text", ""))):
        if len(r) < 4 or r[0] == "date":
            continue
        try:
            d, habit, v = date.fromisoformat(r[0]), r[2], float(r[3])
        except ValueError:
            continue
        days.setdefault(habit, {})
        days[habit][d] = days[habit].get(d, 0) + v
    if not days:
        return {"text": "# Habits this week\n\nNo entries yet. Run Daily habit tracker first.\n", "habits": 0}
    lines = ["# Habits this week (to %s)\n" % today, "| habit | days done | total | streak | best day |", "|---|---|---|---|---|"]
    for habit in sorted(days):
        per = days[habit]
        done = sorted(d for d in per if d in week)
        total = sum(per[d] for d in done)
        streak, d = 0, today if today in per else today - timedelta(days=1)
        while d in per:
            streak += 1
            d -= timedelta(days=1)
        best = max(done, key=lambda x: per[x]) if done else None
        lines.append("| %s | %d/7 | %g | %d | %s |" % (habit, len(done), total, streak,
                     "%s (%g)" % (best, per[best]) if best else "-"))
    return {"text": "\n".join(lines) + "\n", "habits": len(days)}
